G=load(); print(sorted(G))
# Hypothesis: fill all 4-connected background cells NOT on the border with the accent color.
for n in range(1,6):
    inp=G[f'Demo pair {n} input']; out=G[f'Demo pair {n} output']
    H,W=len(inp),len(inp[0])
    cnt=Counter(v for row in inp for v in row); bg=cnt.most_common(1)[0][0]
    acc=min({v for v in cnt}-{bg},key=lambda v:cnt[v])
    vis=[[False]*W for _ in range(H)]
