        for i in (0,H-1):
            if inp[i][j]==bg and not vis[i][j]: vis[i][j]=True; q.append((i,j))
    while q:
        i,j=q.pop()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and not vis[a][b] and inp[a][b]==bg:
                vis[a][b]=True; q.append((a,b))
